    tester,
  ) async {
    final service = _PhaseService()
      ..rows.add(FaChatMessage(role: 'user', content: 'tidy the repo'))
      ..streaming = true
      ..notify();
    await _pump(tester, service);
    // Request out, nothing running yet: the provider wait.
