        prev=line; out+=line
    return w,h,ch,bytes(out)

def bands(name):
    w,h,ch,px=load_png(f'/tmp/gold/{name}.png')
    rows=[]
    for y in range(h):
        found=False
        for x in range(0,w,2):
            i=(y*w+x)*ch
            r,g,b=px[i],px[i+1],px[i+2]
            if b>140 and b-r>40 and b-g>60:
                found=True; break
        rows.append(found)
    out=[]; y=0
    while y<h:
        if rows[y]:
            y0=y
            while y<h and rows[y]: y+=1
            if y-y0>=6: out.append((y0,y))
        y+=1
    print(f'{name}: {w}x{h} bands={out}')

for n in ('empty_new','empty_dark','sheet_old','sheet_new'): bands(n)
