import zlib, struct

def load_png(path):
    with open(path,'rb') as f: data=f.read()
    pos=8; w=h=None; idat=b''; ctype=None
    while pos<len(data):
        ln=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8]
        chunk=data[pos+8:pos+8+ln]
        if typ==b'IHDR':
            w,h,bd,ctype,comp,filt,inter=struct.unpack('>IIBBBBB',chunk)
        elif typ==b'IDAT': idat+=chunk
        pos+=12+ln
    raw=zlib.decompress(idat)
    ch={0:1,2:3,4:2,6:4}[ctype]
    stride=w*ch
    out=bytearray(); prev=bytearray(stride); i=0
    for y in range(h):
        ft=raw[i]; i+=1
        line=bytearray(raw[i:i+stride]); i+=stride
        if ft==1:
            for x in range(ch,stride): line[x]=(line[x]+line[x-ch])&0xff
        elif ft==2:
            for x in range(stride): line[x]=(line[x]+prev[x])&0xff
        elif ft==3:
            for x in range(stride):
                a=line[x-ch] if x>=ch else 0
                line[x]=(line[x]+((a+prev[x])>>1))&0xff
        elif ft==4:
            for x in range(stride):
                a=line[x-ch] if x>=ch else 0
                b=prev[x]; c=prev[x-ch] if x>=ch else 0
                p=a+b-c; pa=abs(p-a); pb=abs(p-b); pc=abs(p-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[x]=(line[x]+pr)&0xff
        prev=line; out+=line
    return w,h,ch,bytes(out)

def bands(name):
    w,h,ch,px=load_png(f'/tmp/gold/{name}.png')
    rows=[]
    for y in range(h):
        found=False
        for x in range(0,w,2):
            i=(y*w+x)*ch
            r,g,b=px[i],px[i+1],px[i+2]
            if b>140 and b-r>40 and b-g>60:
                found=True; break
        rows.append(found)
    out=[]; y=0
    while y<h:
        if rows[y]:
            y0=y
            while y<h and rows[y]: y+=1
            if y-y0>=6: out.append((y0,y))
        y+=1
    print(f'{name}: {w}x{h} bands={out}')

